var EXTRA=[{dot:"gray",j:"Arthroscopy",h:"Le lesioni radiali del menisco restano difficili da trattare bene",v:"Un commento editoriale che accompagna il consenso Delphi sulle lesioni radiali del menisco ribadisce che qualita' del tessuto, allineamento e grado di artrosi vanno sempre considerati nelle lesioni degenerative, e che le lesioni acute complete richiedono familiarita' con piu' tecniche di sutura.",pmid:'42701894',doi:'10.1002/arj.70468',temi:["menisco","commento editoriale"]},{dot:"gray",j:"Journal of Orthopaedic Case Reports",h:"Anche con lo score Kitaoka, il prelievo del peroneo lungo per il LCA e' sicuro",v:"Uno studio di coorte prospettico indiano conferma, con lo score funzionale della caviglia di Kitaoka, un recupero quasi completo della funzione della caviglia donatrice a sei mesi dal prelievo del tendine del peroneo lungo per la ricostruzione del LCA — innesto che tu non usi.",pmid:'42713078',doi:'10.13107/jocr.2026.v16.i09.8112',temi:["lca","innesto alternativo"]},{dot:"gray",j:"Zhonghua Yi Xue Za Zhi",h:"Verso una protesi monocompartimentale piu' precisa e su misura del paziente",v:"Una rassegna cinese ripercorre l'evoluzione della protesi monocompartimentale verso pianificazione assistita da intelligenza artificiale, strumentario paziente-specifico stampato in 3D e chirurgia robotica, segnalando che lo standard di riferimento per il posizionamento dell'impianto resta indefinito.",pmid:'42778312',doi:'10.3760/cma.j.cn112137-20260105-00048',temi:["protesi monocompartimentale","chirurgia robotica"]},{dot:"gray",j:"The Knee",h:"Come l'intelligenza artificiale legge le radiografie dell'artrosi di ginocchio",v:"Una rassegna comparativa ripercorre un decennio di modelli di apprendimento automatico per classificare l'artrosi di ginocchio da radiografie, dai descrittori disegnati a mano alle reti neurali profonde, evidenziando gli ostacoli ancora aperti verso l'uso clinico reale.",pmid:'42759158',doi:'10.1016/j.knee.2026.104634',temi:["intelligenza artificiale","artrosi"]}];
var SCOPERTE=[{t:"Una rete neurale ibrida impara a leggere lo stress di contatto del ginocchio in tempo reale",v:"Un gruppo di bioingegneria della Peking University confronta cinque architetture di rete neurale su grafo per riprodurre, in tempi quasi reali, l'analisi agli elementi finiti dello stress di contatto del ginocchio durante cambi di direzione nel calcio; il modello ibrido, che combina diffusione locale e instradamento globale dell'informazione, riduce l'errore quadratico medio del 20% rispetto al modello di base (RMSE 0,044±0,005 contro 0,055±0,008; p=0,039) e identifica meglio le zone ad alto rischio. Vale la deviazione perche' mostra dove sta andando la modellazione biomeccanica computazionale del tuo stesso interesse per l'intelligenza artificiale in medicina, applicata qui al gesto sportivo che piu' spesso porta al tuo ambulatorio.",pmid:'42709326',doi:'10.1007/s11517-026-03675-0',temi:["intelligenza artificiale","bioingegneria"]},{t:"Un'intelligenza artificiale spiega se stessa mentre classifica l'artrosi di ginocchio dalle radiografie",v:"Un gruppo saudita combina una rete convoluzionale con un modulo di attenzione e mappe di calore interpretabili per classificare la gravita' dell'artrosi di ginocchio su 9.786 radiografie, raggiungendo un'accuratezza del 93,9% e un'area sotto la curva ROC di 0,948; l'82,7% delle mappe di attenzione e' stato giudicato clinicamente rilevante da esperti, e su una coorte esterna l'accuratezza resta all'86,2%. Vale la deviazione perche' e' un altro tassello della stessa domanda che ti interessa: non solo se l'intelligenza artificiale funziona, ma se un medico puo' fidarsi del perche' arriva a una certa risposta.",pmid:'42741032',doi:'10.3389/fmed.2026.1925244',temi:["intelligenza artificiale","imaging"]},{t:"Un braccialetto che cammina con il paziente prova a prevedere il peggioramento dell'artrosi",v:"Un gruppo di Shanghai integra dati clinici, analisi del cammino e un dispositivo indossabile che segue l'attivita' quotidiana per prevedere, su 984 pazienti, chi vedra' peggiorare il proprio dolore da artrosi di ginocchio nell'anno successivo; il modello che unisce tutte le fonti raggiunge un'area sotto la curva dello 0,815 contro lo 0,673 del solo modello clinico. Vale la deviazione perche' e' la stessa idea del monitoraggio continuo applicata a una domanda molto concreta: chi, fra i tuoi pazienti con artrosi lieve, sta per peggiorare davvero.",pmid:'42769271',doi:'10.62347/ORTB8274',temi:["intelligenza artificiale","dispositivi indossabili"]}];
var SOC={"1": {"video": "Oggi parliamo di due infiltrazioni molto diffuse contro l'artrosi di ginocchio: il plasma ricco di piastrine, ricavato da un prelievo di sangue del paziente stesso, e l'acido ialuronico. Una nuova revisione ha messo insieme ventotto studi randomizzati, quasi duemilasettecento pazienti in tutto, ed e' la sintesi piu' ampia fatta finora su questo confronto diretto. Il risultato: il plasma ricco di piastrine riduce di piu' il dolore e migliora di piu' la funzione del ginocchio rispetto all'acido ialuronico. Il vantaggio e' piu' netto quando il plasma contiene pochi globuli bianchi, quando si fanno piu' infiltrazioni nel tempo, e nell'artrosi non troppo avanzata. Il punto onesto: il modo di preparare il plasma cambia molto da uno studio all'altro, e questo rende il confronto meno netto di quanto sembri a prima vista. Non e' un trattamento chirurgico, ma e' spesso la prima scelta prima di parlare di intervento, ed e' utile sapere quale infiltrazione ha oggi le prove migliori dalla sua parte.", "linkedin": "Meta-analisi di 28 RCT (2.685 pazienti) su plasma ricco di piastrine (PRP) contro acido ialuronico (HA) intra-articolare nell'artrosi di ginocchio, Journal of ISAKOS, settembre 2026. Il PRP migliora di piu' il WOMAC totale (DM -8,14; IC 95% -10,79/-5,48; p<0,00001) e il dolore VAS (DM -7,89; IC 95% -12,90/-2,89; p=0,002) rispetto all'HA, con effetto maggiore per PRP a basso contenuto leucocitario, protocolli a infiltrazioni multiple e artrosi Kellgren-Lawrence I-II. Certezza GRADE moderata per il WOMAC, bassa per il dolore. Limite dichiarato: eterogeneita' molto alta (I²=96-97%) e preparazione del PRP non standardizzata fra i 28 trial; restringendo l'analisi ai soli studi a basso rischio di bias il vantaggio si attenua ma non scompare.", "instagram": "💉 Artrosi di ginocchio: plasma ricco di piastrine o acido ialuronico, quale infiltrazione aiuta di piu'?\n\nUna revisione di 28 studi randomizzati e quasi 2.700 pazienti dice: il plasma ricco di piastrine (ricavato dal sangue del paziente) riduce di piu' il dolore e migliora di piu' la funzione, soprattutto nelle forme di artrosi meno avanzate.\n\nIl limite: il modo di prepararlo cambia da centro a centro, e questo rende il confronto meno netto di quanto sembri.", "pazienti": "Per l'artrosi di ginocchio si usano spesso infiltrazioni di acido ialuronico o di plasma ricco di piastrine, quest'ultimo ricavato da un semplice prelievo di sangue del paziente e poi concentrato. Una nuova revisione ha messo insieme i risultati di ventotto studi di alta qualita', per un totale di quasi 2.700 pazienti trattati con l'una o con l'altra infiltrazione.\n\nIl risultato: chi ha ricevuto il plasma ricco di piastrine ha avuto, in media, un miglioramento leggermente maggiore del dolore e del movimento del ginocchio rispetto a chi ha ricevuto l'acido ialuronico. Il vantaggio e' piu' evidente quando il plasma viene preparato con pochi globuli bianchi, quando si fanno piu' infiltrazioni nel tempo, e nelle forme di artrosi meno avanzate.\n\nUn punto va detto con chiarezza: i modi di preparare il plasma ricco di piastrine cambiano molto da un centro all'altro, e gli stessi autori dello studio invitano a interpretare questo vantaggio con una preparazione ancora non standardizzata in mente. L'acido ialuronico resta comunque un'alternativa ragionevole."}};
var SOCV={"1": {"video": {"chir": ["Una meta-analisi di 28 RCT, 2.685 pazienti, pubblicata su Journal of ISAKOS a settembre 2026, confronta plasma ricco di piastrine (PRP) e acido ialuronico (HA) intra-articolari nell'artrosi di ginocchio sintomatica. Il PRP migliora di piu' il WOMAC totale, con differenza media di -8,14 punti, e il dolore su scala VAS, con differenza media di -7,89 punti, entrambi statisticamente significativi rispetto all'HA.", "L'effetto e' maggiore con PRP a basso contenuto leucocitario, con protocolli a infiltrazioni multiple e nell'artrosi Kellgren-Lawrence I-II; questi tre fattori spiegano circa un quarto della variabilita' fra gli studi. Restringendo l'analisi ai soli trial a basso rischio di bias, il vantaggio del PRP si riduce ma resta presente; nessuna asimmetria significativa del funnel plot suggerisce l'assenza di bias di pubblicazione evidente.", "Il limite piu' importante: la preparazione del PRP non e' standardizzata fra i 28 trial inclusi, ed e' proprio questa variabilita' a spiegare parte dell'eterogeneita' molto alta osservata. Resta la sintesi piu' ampia disponibile finora su questo confronto diretto, e il messaggio per la pratica quotidiana e' chiaro: a certezza moderata per la funzione e bassa per il dolore, il PRP ha oggi le prove migliori dalla sua parte, soprattutto a basso contenuto leucocitario."], "misto": ["Una nuova revisione ha messo insieme ventotto studi randomizzati, il tipo di studio piu' affidabile in medicina, per un totale di quasi 2.700 pazienti trattati per artrosi di ginocchio con due infiltrazioni molto diffuse: il plasma ricco di piastrine, ricavato dal sangue del paziente, e l'acido ialuronico. Il risultato: chi ha ricevuto il plasma ricco di piastrine ha avuto un miglioramento maggiore sia del dolore sia della funzione del ginocchio.", "Il vantaggio e' piu' netto quando il plasma viene preparato con pochi globuli bianchi, quando si fanno piu' infiltrazioni nel tempo invece di una sola, e nelle forme di artrosi meno avanzate. Anche guardando solo gli studi di qualita' migliore, il vantaggio del plasma resta, anche se un po' piu' piccolo.", "Il punto da tenere a mente: i modi di preparare il plasma ricco di piastrine cambiano molto da un centro all'altro, e questo rende il confronto meno netto di quanto potrebbe sembrare. Per chi sta valutando un'infiltrazione prima di pensare a un intervento chirurgico, questa e' oggi la sintesi piu' ampia disponibile sul confronto fra le due opzioni piu' usate."], "pazienti": ["Per l'artrosi di ginocchio si usano spesso due tipi di infiltrazione: l'acido ialuronico e il plasma ricco di piastrine, quest'ultimo ricavato da un semplice prelievo di sangue del paziente. Una grande revisione che ha messo insieme quasi 2.700 pazienti mostra che il plasma ricco di piastrine da' in media un miglioramento un po' maggiore del dolore e del movimento del ginocchio.", "Il vantaggio si vede meglio quando il plasma viene preparato in un certo modo, quando si fanno piu' infiltrazioni nel tempo, e nelle forme di artrosi non troppo avanzate.", "Un avvertimento onesto: il modo di preparare il plasma ricco di piastrine cambia da un centro all'altro, e questo rende meno certo quanto il vantaggio sia sempre lo stesso per tutti. L'acido ialuronico resta comunque una scelta ragionevole, soprattutto dove il plasma non e' disponibile."]}, "linkedin": {"chir": ["Meta-analisi di 28 RCT (2.685 pazienti) su PRP vs HA intra-articolare nell'artrosi di ginocchio, J ISAKOS, set 2026: il PRP supera l'HA su WOMAC (DM -8,14; IC 95% -10,79/-5,48; p<0,00001) e VAS dolore (DM -7,89; IC 95% -12,90/-2,89; p=0,002).", "Effetto maggiore con PRP a basso contenuto leucocitario, infiltrazioni multiple e K-L I-II (tutte p-interazione <0,05); questi fattori spiegano circa il 24% della varianza fra studi. Il vantaggio si attenua ma resta restringendo l'analisi ai trial a basso rischio di bias.", "Limite: eterogeneita' molto alta (I²=96-97%) legata soprattutto alla preparazione del PRP, mai standardizzata fra i 28 trial. Certezza GRADE moderata sul WOMAC, bassa sul dolore: la sintesi piu' ampia finora, con un limite che vale la pena dichiarare a ogni paziente."], "misto": ["Una revisione di 28 studi randomizzati (quasi 2.700 pazienti) confronta due infiltrazioni per l'artrosi di ginocchio: il plasma ricco di piastrine e l'acido ialuronico. Il plasma ricco di piastrine vince su dolore e funzione, con un vantaggio piu' netto a basso contenuto di globuli bianchi e con piu' infiltrazioni nel tempo.", "Il vantaggio resta, anche se piu' piccolo, guardando solo gli studi di qualita' migliore.", "Il limite: il modo di preparare il plasma cambia molto da un centro all'altro. E' comunque la sintesi piu' ampia oggi disponibile su questo confronto diretto."], "pazienti": ["Artrosi di ginocchio: plasma ricco di piastrine o acido ialuronico? Una revisione di quasi 2.700 pazienti dice che il plasma da' in media un miglioramento un po' maggiore di dolore e movimento.", "Il vantaggio si vede meglio con pochi globuli bianchi nel preparato, piu' infiltrazioni nel tempo, e artrosi non troppo avanzata.", "Il modo di preparare il plasma varia da centro a centro: un limite onesto da tenere a mente. L'acido ialuronico resta comunque una scelta valida."]}, "instagram": {"chir": ["💉📊 28 RCT, 2.685 pazienti: PRP batte HA su WOMAC e VAS dolore nell'artrosi di ginocchio (p<0,00001 e p=0,002).", "Effetto maggiore con PRP a basso contenuto leucocitario, piu' infiltrazioni, K-L I-II. Resta anche nei soli studi a basso rischio di bias.", "Limite: eterogeneita' alta (I²=96-97%), preparazione del PRP non standardizzata. Certezza GRADE moderata-bassa."], "misto": ["💉 Artrosi di ginocchio: plasma ricco di piastrine o acido ialuronico? Una revisione di quasi 2.700 pazienti dice: il plasma vince su dolore e funzione.", "Il vantaggio e' piu' netto con poche cellule bianche nel preparato, piu' infiltrazioni, artrosi meno avanzata.", "Il limite: la preparazione del plasma varia molto da centro a centro."], "pazienti": ["💉 Quale infiltrazione aiuta di piu' nell'artrosi di ginocchio?", "Una revisione su quasi 2.700 pazienti dice: il plasma ricco di piastrine da' in media un miglioramento un po' maggiore di dolore e movimento rispetto all'acido ialuronico.", "Il modo di prepararlo cambia da centro a centro: un limite onesto da conoscere prima di scegliere."]}, "reel": {"chir": ["[PRP O ACIDO IALURONICO NELL'ARTROSI?] 28 RCT, 2.685 pazienti: il PRP vince su WOMAC e dolore VAS.", "[PERCHE'] Effetto maggiore a basso contenuto leucocitario, piu' infiltrazioni, artrosi meno avanzata.", "[IL LIMITE] Preparazione del PRP non standardizzata fra gli studi: eterogeneita' molto alta."], "misto": ["[QUALE INFILTRAZIONE FUNZIONA DI PIU' PER L'ARTROSI?] Una revisione di 28 studi confronta plasma ricco di piastrine e acido ialuronico.", "[IL RISULTATO] Il plasma vince su dolore e funzione, soprattutto con poche infiltrazioni ben scelte nel tempo.", "[IL LIMITE] Il modo di prepararlo cambia molto da un centro all'altro."], "pazienti": ["[ARTROSI DI GINOCCHIO: QUALE INFILTRAZIONE SCEGLIERE?] Plasma ricco di piastrine o acido ialuronico?", "[COSA DICE LA SCIENZA] Su quasi 2.700 pazienti, il plasma da' un miglioramento un po' maggiore di dolore e movimento.", "[DA SAPERE] Il modo di prepararlo varia da centro a centro: chiedilo sempre al tuo chirurgo."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #ArtrosiDelGinocchio #MedicinaRigenerativa", "instagram": "#ortopedia #artrosiginocchio #plasmaricchodipiastrine #acidoialuronico #medicinasportiva #ginocchio #ortopedico #chirurgiaortopedica #infiltrazioni #curadelginocchio", "kw": "PRP ginocchio, plasma ricco di piastrine artrosi, acido ialuronico ginocchio"}};
var NLB={"1": {"prof": ["Artrosi di ginocchio: il PRP supera l'acido ialuronico in una meta-analisi di 28 RCT", "Una meta-analisi di 28 RCT (2.685 pazienti) mostra un vantaggio del plasma ricco di piastrine sull'acido ialuronico su WOMAC (DM -8,14) e dolore VAS (DM -7,89), maggiore con PRP a basso contenuto leucocitario e infiltrazioni multiple.", "Nota critica: eterogeneita' molto alta fra gli studi (I²=96-97%) e preparazione del PRP non standardizzata; il vantaggio si attenua, senza sparire, restringendo l'analisi ai soli studi a basso rischio di bias."], "mix": ["Artrosi di ginocchio: un'infiltrazione batte l'altra in un grande confronto", "Un confronto fra due infiltrazioni molto usate per l'artrosi di ginocchio — il plasma ricco di piastrine, ricavato dal sangue del paziente, e l'acido ialuronico — su quasi 2.700 pazienti mostra un miglioramento maggiore del dolore e della funzione con il plasma ricco di piastrine, soprattutto in forme di artrosi non troppo avanzate.", "Nota sul limite: i modi di preparare il plasma ricco di piastrine variano molto da uno studio all'altro, e questo rende il confronto meno netto di quanto sembri a prima vista."], "paz": ["L'infiltrazione che aiuta di piu' nell'artrosi di ginocchio, secondo un grande confronto", "Per l'artrosi di ginocchio si usano spesso infiltrazioni di acido ialuronico o di plasma ricco di piastrine, ricavato da un prelievo di sangue del paziente stesso. Un'analisi che ha messo insieme quasi 2.700 pazienti trattati con l'uno o con l'altro mostra un miglioramento del dolore e del movimento leggermente maggiore con il plasma ricco di piastrine.", "Il modo in cui viene preparato il plasma cambia da centro a centro, e questo rende difficile dire con certezza quanto il vantaggio sia sempre uguale per tutti."], "kw": "PRP ginocchio, acido ialuronico ginocchio, artrosi ginocchio infiltrazioni"}, "2": {"prof": ["Instabilita' antero-mediale dopo LCA: un condilo femorale stretto come possibile fattore di rischio", "In 141 ginocchia, una minore larghezza del condilo femorale mediale (MFCW) si associa a instabilita' rotatoria antero-mediale dopo lesione del LCA, insieme a lesioni ecografiche del collaterale mediale profondo (89,7%) e del retinacolo antero-mediale (63,8%).", "Nota critica: studio retrospettivo di livello IV, senza dati di esito chirurgico; il gruppo di controllo ha una lesione meniscale isolata, non un ginocchio sano."], "mix": ["Un osso piu' stretto dietro l'instabilita' del ginocchio dopo la rottura del legamento crociato", "In uno studio su 141 pazienti con rottura del legamento crociato anteriore, chi aveva anche un'instabilita' rotatoria del lato interno del ginocchio aveva, alla risonanza, un osso del femore (il condilo mediale) piu' stretto della media, insieme a lesioni associate dei legamenti del lato interno.", "Nota sul limite: lo studio guarda indietro nel tempo e non dice se operare in modo diverso in base a questa misura cambi davvero il risultato per il paziente."], "paz": ["Un dettaglio dell'osso del ginocchio che puo' nascondere un'instabilita' in piu'", "Dopo la rottura del legamento crociato anteriore, alcuni ginocchi risultano piu' instabili di altri anche verso l'interno. Uno studio su 141 pazienti suggerisce che chi ha un osso del femore leggermente piu' stretto in un punto preciso ha piu' spesso anche questo tipo di instabilita' aggiuntiva, insieme a lesioni dei legamenti del lato interno del ginocchio.", "E' un'osservazione utile per orientare la visita, non una regola valida per ogni paziente: lo studio guarda indietro nel tempo e non segue i pazienti dopo l'intervento."], "kw": "instabilita' ginocchio LCA, lesione legamento crociato, instabilita' antero-mediale"}, "3": {"prof": ["Protesi di ginocchio senza cemento con interfaccia 3D: non inferiore alla cementata a breve termine", "In 79 pazienti, la protesi totale di ginocchio senza cemento con interfaccia in metallo trabecolare stampata in 3D non mostra svantaggi sulla protesi cementata per punteggio KSS, complicanze o sopravvivenza a circa 28 mesi (100% contro 95%, non significativo).", "Nota critica: studio retrospettivo monocentrico, follow-up breve per giudicare la fissazione a lungo termine, campione piccolo per le complicanze."], "mix": ["Protesi di ginocchio senza cemento: un'alternativa che regge il confronto a breve termine", "Uno studio cinese confronta una protesi di ginocchio fissata senza cemento, con una superficie stampata in 3D pensata per far crescere l'osso al suo interno, con la tradizionale protesi cementata: a poco piu' di due anni, funzione, complicanze e tenuta dell'impianto sono risultate simili.", "Nota sul limite: il tempo di osservazione (circa due anni e mezzo) e' ancora troppo breve per giudicare la tenuta di una fissazione senza cemento nel lungo periodo, quando di solito emergono le differenze."], "paz": ["Protesi di ginocchio senza cemento: funziona altrettanto bene?", "Esistono due modi principali per fissare una protesi di ginocchio all'osso: con il cemento osseo, il piu' diffuso, oppure senza cemento, lasciando che l'osso cresca dentro una superficie porosa dell'impianto. Uno studio su 79 pazienti operati con l'una o l'altra tecnica non ha trovato differenze importanti nella ripresa funzionale ne' nelle complicanze a circa due anni e mezzo.", "E' un risultato incoraggiante ma ancora presto: serve piu' tempo di osservazione prima di sapere se le due tecniche tengono allo stesso modo nel lungo periodo."], "kw": "protesi ginocchio senza cemento, protesi ginocchio 3D, artroplastica ginocchio"}, "4": {"prof": ["Rigidita' del tendine rotuleo e forza del quadricipite predicono l'artrosi futura", "In una coorte prospettica di 220 ginocchia asintomatiche, la rigidita' del tendine rotuleo e la forza degli estensori del ginocchio predicono l'artrosi clinica incidente a 2 anni (C-index 0,720); il terzile a rischio piu' alto ha un'incidenza del 38,4% contro il 17,6% del terzile piu' basso.", "Nota critica: coorte monocentrica di 116 partecipanti, 55 eventi — potenza limitata, risultati esplorativi non ancora validati esternamente."], "mix": ["Muscoli e tendine del ginocchio possono anticipare i segnali dell'artrosi futura", "In un gruppo di anziani senza dolore al ginocchio, misurare quanto e' rigido il tendine sotto la rotula e quanto e' forte il muscolo quadricipite ha permesso di prevedere, con discreta precisione, chi avrebbe sviluppato artrosi sintomatica nei due anni successivi.", "Nota sul limite: lo studio e' ancora piccolo (116 persone) e va confermato su gruppi piu' grandi prima di poter essere usato come vero strumento di screening."], "paz": ["Il ginocchio puo' dare segnali di artrosi prima ancora del dolore?", "In un gruppo di persone anziane senza alcun dolore al ginocchio, misurare la forza del muscolo davanti alla coscia e la rigidita' del tendine sotto la rotula ha aiutato a individuare, con due anni di anticipo, chi avrebbe sviluppato artrosi sintomatica.", "E' una ricerca ancora preliminare, su un numero limitato di persone: non e' (ancora) un esame da richiedere in ambulatorio, ma indica una direzione interessante per la prevenzione."], "kw": "artrosi ginocchio prevenzione, forza quadricipite, tendine rotuleo"}, "5": {"prof": ["Infiltrazione di PRP ricco di leucociti nell'artrosi: una casistica giapponese senza controllo", "In una serie di casi retrospettiva su 15 ginocchia (Kellgren-Lawrence II-III), un'infiltrazione di plasma ricco di piastrine ricco di leucociti (sistema GPS) si associa a un miglioramento del dolore NRS a 1 anno (-1,9 punti) e della qualita' di vita KOOS (+15,4 punti).", "Nota critica: serie di casi non controllata, senza confronto ne' cecita'; 5 pazienti su 20 persi al follow-up; non dimostra efficacia ne' sicurezza."], "mix": ["Un'infiltrazione di plasma per l'artrosi: un miglioramento visto, ma senza confronto", "In un piccolo gruppo di 15 pazienti giapponesi con artrosi di ginocchio, un'infiltrazione di un tipo particolare di plasma ricco di piastrine (che contiene anche globuli bianchi) e' stata seguita da un miglioramento del dolore e della qualita' di vita a un anno di distanza.", "Nota sul limite: non c'e' stato alcun gruppo di confronto che non ha ricevuto l'infiltrazione, quindi non si puo' dire con certezza se il miglioramento sia dovuto al trattamento o al semplice andamento naturale dell'artrosi."], "paz": ["Un'infiltrazione per l'artrosi che sembra aiutare: ma serve cautela", "Un piccolo studio giapponese ha seguito per un anno 15 pazienti con artrosi di ginocchio trattati con un'infiltrazione di plasma ricco di piastrine ricavato dal loro stesso sangue, osservando un miglioramento del dolore nella maggior parte dei casi.", "Senza un gruppo di pazienti non trattati con cui confrontarsi, pero', non si puo' sapere con certezza quanto di questo miglioramento sia dovuto davvero all'infiltrazione: sono risultati preliminari, da prendere con cautela."], "kw": "PRP artrosi ginocchio, infiltrazione ginocchio, plasma ricco piastrine"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of ISAKOS",h:"Il plasma ricco di piastrine batte l'acido ialuronico nell'artrosi",v:"Meta-analisi di 28 RCT (2.685 pazienti): il PRP riduce dolore e disabilita' piu' dell'acido ialuronico, soprattutto a basso contenuto leucocitario.",ax:"Alshehri, Sharaf, Almokhtar, Alamri",date:"set 2026",meta:"meta-analisi di 28 RCT, 2.685 pazienti, GRADE moderata-bassa · [I]",pmid:'42744121',doi:'10.1016/j.jisako.2026.101218',journal:"Journal of ISAKOS : joint disorders & orthopaedic sports medicine",authors:"Alshehri D, Sharaf RM, Almokhtar AA, Alamri MK",design:"Revisione sistematica e meta-analisi di RCT che confrontano infiltrazione intra-articolare di plasma ricco di piastrine (PRP) con acido ialuronico (HA) nell'artrosi di ginocchio sintomatica; ricerca su PubMed/MEDLINE, EMBASE e Cochrane CENTRAL dall'inizio delle banche dati al 14 aprile 2026, senza restrizioni di lingua o data; pooling a effetti casuali, sottogruppi pre-specificati (contenuto leucocitario del PRP, numero di infiltrazioni, gravita' radiografica, durata del follow-up), meta-regressione; certezza valutata con GRADE.",pop:"28 RCT, 2.685 pazienti adulti con artrosi di ginocchio sintomatica, trattati con PRP o HA intra-articolare.",results:"Il PRP migliora di piu' il punteggio WOMAC totale (differenza media, DM, -8,14; IC 95% -10,79/-5,48; p<0,00001; I²=96%) e il dolore su scala VAS (DM -7,89; IC 95% -12,90/-2,89; p=0,002; I²=97%) rispetto all'HA. L'effetto e' maggiore con PRP a basso contenuto leucocitario (p-interazione=0,04), con protocolli a infiltrazioni multiple (p-interazione=0,04) e nell'artrosi Kellgren-Lawrence I-II (p-interazione=0,03); severita' e numero di infiltrazioni spiegano circa il 24% della varianza fra studi. Restringendo l'analisi agli studi a basso rischio di bias il vantaggio del PRP si attenua ma non scompare; nessuna asimmetria significativa del funnel plot (Egger p=0,21 per WOMAC, p=0,24 per VAS).",concl:"Gli autori concludono che il PRP intra-articolare produce un miglioramento funzionale maggiore dell'HA con certezza moderata e un sollievo dal dolore maggiore con certezza bassa; il beneficio piu' ampio e' atteso nella malattia lieve-moderata trattata con PRP a basso contenuto leucocitario in protocolli a infiltrazioni multiple, e l'HA resta un'alternativa ragionevole.",limits:"Eterogeneita' molto alta fra gli studi (I²=96-97%) · preparazione e caratterizzazione del PRP non standardizzate fra i 28 trial inclusi · nessuna registrazione prospettica del protocollo di revisione dichiarata nell'abstract.",perte:"Non e' la tua pratica chirurgica, ma e' la conversazione che hai con ogni paziente con gonartrosi lieve-moderata prima di parlare di intervento: la sintesi piu' ampia finora dice che il PRP, soprattutto a basso contenuto leucocitario e a infiltrazioni multiple, batte l'HA — con il limite di una preparazione del PRP ancora non standardizzata fra gli studi."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Un femore stretto si associa a instabilita' rotatoria antero-mediale dopo LCA",v:"Studio comparativo su 141 ginocchia: una minore larghezza del condilo femorale mediale si associa a instabilita' antero-mediale dopo lesione del LCA, con lesioni combinate del collaterale mediale profondo e del retinacolo antero-mediale.",ax:"Wu, Zhang, Liu, Zheng, Li, Dong",date:"set 2026",meta:"studio comparativo retrospettivo, 141 ginocchia · [IV]",pmid:'42724688',doi:'10.1002/ars2.70073',journal:"Arthroscopy, sports medicine, and rehabilitation",authors:"Wu S, Zhang R, Liu Y, Zheng Y, Li Z, Dong J",design:"Studio comparativo retrospettivo su pazienti con rottura del LCA suddivisi, in base all'esame sotto anestesia, in un gruppo con instabilita' rotatoria antero-mediale (AMRI: cassetto anteriore e test di Slocum positivi) e un gruppo con LCA isolato (Slocum negativo); un terzo gruppo di controllo con sola lesione meniscale isolata. Fattori morfologici ossei misurati alla RM preoperatoria (rapporto del condilo femorale laterale, larghezza del condilo femorale mediale — MFCW —, larghezza dell'incisura, slope tibiale); lesioni strutturali mediali (collaterale mediale superficiale e profondo, retinacolo antero-mediale) valutate con ecografia e RM.",pop:"141 pazienti di 16-55 anni: 58 con AMRI, 25 con LCA isolato senza AMRI, 58 di controllo con lesione meniscale isolata.",results:"Il gruppo AMRI ha una MFCW piu' piccola del controllo (6,72±0,55 contro 7,35±0,51 mm; p<0,001) e un'incisura piu' stretta (1,79±0,29 contro 2,01±0,37; p=0,001), con rapporto del condilo femorale laterale piu' grande (0,672±0,039 contro 0,644±0,043; p=0,001). La MFCW e' piu' piccola nel gruppo AMRI anche rispetto al gruppo LCA isolato senza AMRI (6,72±0,55 contro 7,03±0,37; p=0,033). All'ecografia, lesione del collaterale mediale profondo nell'89,7% e del retinacolo antero-mediale nel 63,8% del gruppo AMRI; la MFCW discrimina l'AMRI dal controllo con area sotto la curva ROC di 0,791.",concl:"Gli autori concludono che una minore larghezza del condilo femorale mediale si associa a instabilita' rotatoria antero-mediale nei pazienti con LCA e lesioni combinate del collaterale mediale profondo e del retinacolo antero-mediale, e propongono la MFCW come possibile fattore di rischio morfologico da considerare nella valutazione preoperatoria.",limits:"Studio retrospettivo di livello IV senza randomizzazione · gruppo di controllo con lesione meniscale isolata, non ginocchia sane · nessun dato di esito chirurgico o di stabilita' postoperatoria riportato.",perte:"Nella tua pratica di ricostruzioni multilegamentose e nella valutazione dell'instabilita' residua, la larghezza del condilo femorale mediale e' un parametro radiologico facile da misurare in piu': un condilo stretto insieme a un test di Slocum positivo puo' indirizzare la ricerca attiva di una lesione mediale profonda associata, prima ancora dell'artroscopia."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Chinese Journal of Reparative and Reconstructive Surgery",h:"Protesi di ginocchio senza cemento con interfaccia 3D: esiti comparabili alla cementata",v:"Studio retrospettivo su 79 pazienti: la protesi totale di ginocchio senza cemento con interfaccia in metallo trabecolare stampata in 3D non mostra svantaggi sulla protesi cementata per funzione, complicanze e sopravvivenza a circa 28 mesi.",ax:"Chai, Sun, Chen, Li, Li",date:"set 2026",meta:"coorte retrospettiva comparativa, 79 pazienti · [III]",pmid:'42749324',doi:'10.7507/1002-1892.202605035',journal:"Zhongguo xiu fu chong jian wai ke za zhi = Chinese journal of reparative and reconstructive surgery",authors:"Chai H, Sun Y, Chen X, Li Y, Li S",design:"Analisi retrospettiva comparativa fra protesi totale di ginocchio primaria senza cemento con interfaccia in metallo trabecolare stampata in 3D (gruppo cementless) e protesi con stelo posteriore-stabilizzato cementata (gruppo cemented), in pazienti con artropatia di ginocchio in stadio terminale operati fra dicembre 2021 e marzo 2022; confronto su tempo operatorio, perdita ematica intraoperatoria, punteggio KSS clinico e funzionale, radiografie di controllo e sopravvivenza protesica (metodo di Kaplan-Meier).",pop:"79 pazienti: 39 con protesi senza cemento a interfaccia stampata in 3D, 40 con protesi cementata; follow-up medio 28,4±2,4 mesi (cementless) contro 28,2±2,8 mesi (cemented).",results:"Nessuna differenza significativa fra i gruppi su tempo operatorio o perdita ematica intraoperatoria (p>0,05). Entrambi i gruppi hanno migliorato significativamente i punteggi KSS clinico e funzionale rispetto al preoperatorio (p<0,05), senza differenza fra i gruppi nell'entita' del miglioramento (p>0,05). Nessuna mobilizzazione, osteolisi, affondamento protesico o lussazione rilevati radiograficamente in nessun paziente. Complicanze: 12,8% (5/39, cementless) contro 25,0% (10/40, cemented) (p>0,05); sopravvivenza protesica 100,0% (cementless, nessun evento) contro 95,0% (cemented, 2 revisioni per infezione periprotesica e frattura periprotesica) (log-rank p=0,154).",concl:"Gli autori concludono che la protesi senza cemento con interfaccia in metallo trabecolare stampata in 3D non presenta svantaggi evidenti rispetto alla protesi cementata su funzione postoperatoria, tasso di complicanze e sopravvivenza protesica, rappresentando un'opzione sicura e percorribile.",limits:"Studio monocentrico retrospettivo, non randomizzato · follow-up breve-medio (circa 28 mesi), insufficiente per la sopravvivenza a lungo termine dell'interfaccia senza cemento · campione piccolo (79 pazienti) per rilevare differenze in un esito raro come le complicanze.",perte:"Tu operi con il robot VELYS; questo studio non riguarda la componente robotica ma la fissazione dell'impianto — un'interfaccia senza cemento stampata in 3D, diversa dalla fissazione cementata piu' diffusa. E' un primo segnale di non-inferiorita' a follow-up breve, non una dimostrazione di superiorita' ne' un dato sulla sopravvivenza a lungo termine."},{n:4,mono:"m-gray",dot:"gray",sec:"res",j:"JMIR Aging",h:"Tendine rotuleo rigido e quadricipite debole predicono l'artrosi futura",v:"Coorte prospettica di 220 ginocchia asintomatiche: la rigidita' del tendine rotuleo e la forza degli estensori del ginocchio predicono, insieme, l'artrosi clinica incidente a 2 anni.",ax:"Hwang, Li, Xia, Fan, Wong, Kwon, Fu",date:"set 2026",meta:"coorte prospettica, 116 adulti / 220 ginocchia, 2 anni · [II]",pmid:'42784800',doi:'10.2196/84494',journal:"JMIR aging",authors:"Hwang UJ, Li Z, Xia P, Fan T, Wong A, Kwon OY, Fu SN",design:"Studio di coorte prospettico su anziani residenti in comunita', liberi da dolore al ginocchio all'arruolamento; misurate al basale la rigidita' del tendine rotuleo (PTS) e la forza degli estensori del ginocchio (KESt), oltre alla rigidita' passiva del quadricipite; artrosi clinica incidente a 2 anni diagnosticata secondo i criteri ACR; performance prognostica valutata con 7 algoritmi di sopravvivenza e validazione incrociata nested a 5 fold (C-index di Harrell); importanza dei predittori quantificata con valori SHAP.",pop:"116 adulti anziani residenti in comunita' (220 ginocchia), liberi da dolore al ginocchio al basale, seguiti per 2 anni.",results:"55 ginocchia su 220 (25%) hanno sviluppato artrosi clinica incidente entro 2 anni. PTS e KESt sono stati selezionati in tutti i cicli di validazione incrociata, mentre la rigidita' passiva del quadricipite non e' mai stata selezionata. Il modello a gradiente potenziato ha raggiunto la miglior discriminazione (C-index 0,720; IC 95% 0,686-0,754; p<0,05 contro il caso). Il KESt e' il predittore dominante (media |SHAP| 0,314; IC 95% 0,251-0,388), seguito dal PTS (0,166; IC 95% 0,128-0,200). Le ginocchia nel terzile a rischio piu' alto hanno un'incidenza di artrosi a 24 mesi del 38,4% (28/73), piu' del doppio del terzile a rischio piu' basso (17,6%; 13/74).",concl:"Gli autori concludono che la rigidita' del tendine rotuleo e la forza degli estensori del ginocchio predicono in modo indipendente e consistente l'artrosi clinica incidente a 2 anni in anziani asintomatici, e propongono la profilazione meccanica del meccanismo estensore come possibile strumento di identificazione precoce del rischio, da confermare in coorti piu' ampie prima di un uso preventivo o di screening.",limits:"Coorte monocentrica di soli 116 partecipanti (220 ginocchia), 55 eventi — potenza limitata per un C-index definitivo · nessun confronto con la sola valutazione clinica standard come riferimento · risultati esplorativi, non ancora validati esternamente.",perte:"Uno strumento di misura del tendine rotuleo e della forza del quadricipite, gia' nel tuo bagaglio di valutazione biomeccanica, potrebbe un giorno identificare pazienti a rischio di gonartrosi prima che diventino sintomatici — per ora resta un dato di ricerca esplorativo, non uno strumento clinico pronto."},{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"Orthopedic Reviews",h:"Un'infiltrazione di plasma ricco di leucociti nell'artrosi: una casistica giapponese",v:"Serie di casi giapponese non controllata, 15 ginocchia: il dolore migliora a un anno da un'unica infiltrazione di PRP ricco di leucociti (sistema GPS) nell'artrosi Kellgren-Lawrence II-III.",ax:"Maeda, Maeda, Maeda",date:"set 2026",meta:"serie di casi retrospettiva non controllata, 15 ginocchia · [V]",pmid:'42787870',doi:'10.52965/001c.169123',journal:"Orthopedic reviews",authors:"Maeda H, Maeda T, Maeda M",design:"Serie di casi retrospettiva monocentrica su pazienti con artrosi di ginocchio Kellgren-Lawrence II o III sottoposti a una singola infiltrazione intra-articolare di plasma ricco di piastrine ricco di leucociti (sistema GPS, Zimmer Biomet); esito primario il cambiamento del dolore su scala numerica (NRS) a 1 anno; esiti secondari KOOS, Locomo-25, tasso di risposta ed eventi avversi.",pop:"20 pazienti/ginocchia trattati; 15 ginocchia (5 uomini, 10 donne) con dati appaiati basale-1 anno incluse nell'analisi finale, 5 perse al follow-up.",results:"Il dolore NRS e' migliorato da 4,6±2,4 al basale a 2,7±2,1 a 1 anno (variazione media -1,9 punti; IC 95% -3,4/-0,4; p=0,015). La qualita' di vita KOOS e' migliorata da 30,0±17,1 a 45,4±23,8 (variazione media +15,4 punti; IC 95% 4,8/26,0; p=0,010). Gli altri domini KOOS e il Locomo-25 sono migliorati numericamente senza raggiungere la significativita' statistica. Una riduzione del dolore NRS ≥30% si e' verificata in 7 ginocchia su 15 (46,7%), e il dolore e' peggiorato in 2 su 15 (13,3%).",concl:"Gli autori concludono che l'infiltrazione di PRP ricco di leucociti si associa a un miglioramento del dolore e della qualita' di vita KOOS a 1 anno, ma definiscono i risultati preliminari e osservazionali, non dimostrativi di efficacia o sicurezza, e chiedono studi prospettici controllati piu' ampi con caratterizzazione standardizzata del PRP.",limits:"Serie di casi retrospettiva non controllata, senza gruppo di confronto ne' cecita' · solo 15 ginocchia analizzate, 5 perse al follow-up su 20 trattate · nessuna correzione per confronti multipli sui numerosi esiti secondari.",perte:"Un miglioramento a 1 anno senza gruppo di controllo, in soli 15 ginocchi, non distingue l'effetto dell'infiltrazione dalla storia naturale dell'artrosi ne' da un effetto placebo — non e' materiale su cui basare una raccomandazione, ma un segnale preliminare da un dispositivo (GPS, Zimmer Biomet) usato anche nel tuo mercato di riferimento."}];
var SUGGQ=[{"k": "kol", "n": "Jiangtao Dong", "w": "The Third Hospital of Hebei Medical University, Shijiazhuang, Cina", "r": "Ultimo autore della scheda 2 di oggi sulla larghezza del condilo femorale mediale e l'instabilita' antero-mediale dopo lesione del LCA: corrispondenza tecnica diretta con la tua valutazione dell'instabilita' residua e delle lesioni mediali combinate nelle ricostruzioni multilegamentose. Sostituisce la proposta di Kostas J. Economopoulos (26 settembre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="E' domenica: prima il punto sulla settimana, poi il giorno. Da martedi' a ieri il lavoro piu' importante e' stato il tuo stesso FIRM-P, la proposta di un framework che separa il fenotipo dell'instabilita' del LCA in una componente funzionale, individuale, radiologica e meccanica, con l'inibizione muscolare artrogena come modificatore trasversale. Accanto: il current concepts ESSKA a ventisei autori sull'anatomia e l'esame clinico del complesso collaterale mediale; una meta-analisi di nove studi su 910 ginocchia che non trova differenze quando la riparazione della radice meniscale laterale si aggiunge alla ricostruzione del LCA; il confronto Mayo Clinic fra fissazione con ancora e riparazione transtibiale della radice meniscale, la tua tecnica, con uno stato sintomatico accettabile raggiunto piu' spesso con l'ancora ma un follow-up molto piu' corto; e ieri la meta-analisi di 24 RCT che non trova un vantaggio funzionale della protesi robotica sulla convenzionale. La tensione sul rinforzo laterale universale si e' mossa tre volte in modo indiretto, sempre nella direzione della tua pratica senza chiuderla.\n\nOggi il quadro cambia: nessun consensus nuovo, nessuna tensione toccata, e una giornata guidata dalla conversazione che forse hai piu' spesso di ogni intervento, quella sull'infiltrazione giusta per un'artrosi che non e' ancora da operare. La meta-analisi piu' ampia finora sul confronto diretto — 28 RCT, 2.685 pazienti — dice che il plasma ricco di piastrine batte l'acido ialuronico su dolore e funzione, soprattutto a basso contenuto leucocitario e con piu' infiltrazioni nel tempo, con il limite onesto di una preparazione del PRP mai standardizzata fra gli studi. Accanto: un condilo femorale stretto che si associa a instabilita' antero-mediale dopo LCA, una protesi senza cemento stampata in 3D che regge il confronto con la cementata a due anni e mezzo, un modello che predice l'artrosi da tendine rotuleo e forza del quadricipite due anni prima che compaia, e una piccola casistica giapponese di PRP ricco di leucociti, onestamente segnalata come non controllata. Da dichiarare in chiaro: la ricerca di oggi per titolo e data su PubMed non ha funzionato per un guasto del connettore, durato l'intera sessione — il dettaglio e i lavori trovati con il metodo sostitutivo sono nella sezione Rassegna.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "E' domenica, quindi partiamo dalla settimana: il lavoro piu' importante e' stato il tuo, FIRM-P, la proposta per classificare l'instabilita' del LCA in quattro componenti."}, {"chi": "B", "t": "E accanto al tuo lavoro, che cosa ha contato di piu'?"}, {"chi": "A", "t": "Il confronto Mayo Clinic sulla radice meniscale: ancora contro riparazione transtibiale, la tua tecnica. Lo stato sintomatico accettabile arriva piu' spesso con l'ancora, ma il follow-up e' molto piu' corto — non chiude la domanda."}, {"chi": "B", "t": "E ieri la protesi robotica che non batte quella convenzionale."}, {"chi": "A", "t": "Esatto, ventiquattro RCT, nessun vantaggio funzionale, solo un intervento piu' lungo. Oggi invece il tema e' diverso: plasma ricco di piastrine contro acido ialuronico nell'artrosi."}, {"chi": "B", "t": "E chi vince?"}, {"chi": "A", "t": "Il plasma, in una meta-analisi di ventotto studi randomizzati, quasi duemilasettecento pazienti. Vince su dolore e su funzione, soprattutto quando ha pochi globuli bianchi e quando si fanno piu' infiltrazioni nel tempo."}, {"chi": "B", "t": "C'e' un limite, immagino."}, {"chi": "A", "t": "Sì, importante: il modo di preparare il plasma cambia moltissimo da uno studio all'altro, e questo spiega buona parte della variabilita' dei risultati."}, {"chi": "B", "t": "Quindi per un paziente con artrosi lieve, prima di parlare di intervento?"}, {"chi": "A", "t": "Oggi il plasma ha le prove migliori dalla sua parte, ma va detto con onesta' che non tutti i plasmi sono uguali."}, {"chi": "B", "t": "E le altre schede di oggi?"}, {"chi": "A", "t": "Un condilo femorale stretto legato a instabilita' dopo LCA, una protesi senza cemento stampata in 3D che tiene il confronto a due anni e mezzo, e un modello che prevede l'artrosi dal tendine rotuleo e dal quadricipite due anni prima che compaia."}, {"chi": "B", "t": "Nessuna tensione mossa oggi, quindi."}, {"chi": "A", "t": "No, e va detto anche un'altra cosa: la ricerca diretta su PubMed non ha funzionato oggi per un guasto tecnico, e abbiamo dovuto usare un metodo diverso per trovare questi lavori."}];
